import json
import re
from io import StringIO
from typing import Any

import pandas as pd
from fastapi.encoders import jsonable_encoder

from langflow.custom import Component
from langflow.io import HandleInput, Output, TabInput
from langflow.schema import Data, DataFrame, Message


def convert_to_message(v) -> Message:
    return v if isinstance(v, Message) else v.to_message()


def convert_to_data(v: DataFrame | Data | Message | dict) -> Data:
    if isinstance(v, dict):
        return Data(v)
    if isinstance(v, Message):
        return v.to_data()
    return v if isinstance(v, Data) else v.to_data()


def _extract_first_markdown_table(text: str) -> str | None:
    """
    Extract the FIRST markdown table from text.
    A markdown table typically has:
      | col1 | col2 |
      | ---  | ---  |
      | ...  | ...  |
    """
    if not text:
        return None

    lines = [ln.rstrip() for ln in text.splitlines() if ln.strip()]
    table_lines = []

    def is_table_line(ln: str) -> bool:
        # contains at least one pipe and looks like a row
        return "|" in ln

    # Find start: header row + separator row
    for i in range(len(lines) - 1):
        if is_table_line(lines[i]) and is_table_line(lines[i + 1]):
            # separator row contains --- (markdown header separator)
            if re.search(r"\|\s*:?-{3,}:?\s*", lines[i + 1]):
                # Start collecting from header
                table_lines = [lines[i], lines[i + 1]]
                # collect following rows until table ends
                for j in range(i + 2, len(lines)):
                    if is_table_line(lines[j]):
                        table_lines.append(lines[j])
                    else:
                        break
                break

    if len(table_lines) >= 2:
        return "\n".join(table_lines)

    return None


def _markdown_table_to_df(md_table: str) -> pd.DataFrame:
    """
    Convert a markdown table string into a DataFrame with dynamic columns.
    Works even if there are extra leading/trailing pipes.
    """
    raw_lines = [ln.strip() for ln in md_table.splitlines() if ln.strip()]

    # Remove the separator line(s) like: |---|---|
    cleaned_lines = []
    for idx, ln in enumerate(raw_lines):
        # skip separator lines containing only pipes, dashes, colons and spaces
        if re.fullmatch(r"[|\s:\-]+", ln):
            continue
        cleaned_lines.append(ln)

    # Now parse using pandas read_csv with | separator
    s = "\n".join(cleaned_lines)

    df = pd.read_csv(
        StringIO(s),
        sep=r"\|",
        engine="python",
        dtype=str,
    )

    # Remove empty columns created by leading/trailing pipes
    df = df.loc[:, ~df.columns.str.contains("^Unnamed")]

    # Strip whitespace in headers
    df.columns = [c.strip() for c in df.columns]

    # Strip whitespace in all cells + turn NaN into ""
    df = df.fillna("").applymap(lambda x: x.strip() if isinstance(x, str) else x)

    # Drop fully empty columns (sometimes created)
    df = df.loc[:, (df != "").any(axis=0)]

    return df


def convert_to_dataframe(v: DataFrame | Data | Message | dict) -> DataFrame:
    """
    ✅ MAIN FIX:
    If input is Message, extract markdown table from Message.text
    and convert ONLY the table into a DataFrame.
    Dynamic columns are supported.
    """
    if isinstance(v, DataFrame):
        return v

    # If dict -> single-row DataFrame
    if isinstance(v, dict):
        return DataFrame([v])

    # If Data -> try to use its content
    if isinstance(v, Data):
        payload = jsonable_encoder(v.data)
        # If it already looks like list[dict], DataFrame(payload) works
        if isinstance(payload, list):
            try:
                return DataFrame(payload)
            except Exception:
                return DataFrame([{"report": json.dumps(payload, indent=2, ensure_ascii=False)}])

        if isinstance(payload, dict):
            # If it contains "text", parse it like Message.text
            text = payload.get("text") or payload.get("report")
            if isinstance(text, str):
                md = _extract_first_markdown_table(text)
                if md:
                    try:
                        return DataFrame(_markdown_table_to_df(md))
                    except Exception:
                        return DataFrame([{"report": text}])

            return DataFrame([payload])

        return DataFrame([{"report": str(payload)}])

    # ✅ If Message -> parse ONLY the markdown table from message.text
    if isinstance(v, Message):
        text = v.text or ""
        md = _extract_first_markdown_table(text)

        if md:
            try:
                parsed = _markdown_table_to_df(md)
                return DataFrame(parsed)
            except Exception:
                # fallback: store raw report only
                return DataFrame([{"report": text}])

        # no table found -> store as report
        return DataFrame([{"report": text}])

    # fallback
    return DataFrame([{"report": str(v)}])


class TypeConverterComponent(Component):
    display_name = "Type Convert"
    description = "Convert between different types (Message, Data, DataFrame)"
    documentation: str = "https://docs.langflow.org/components-processing#type-convert"
    icon = "repeat"

    inputs = [
        HandleInput(
            name="input_data",
            display_name="Input",
            input_types=["Message", "Data", "DataFrame"],
            info="Accept Message, Data or DataFrame as input",
            required=True,
        ),
        TabInput(
            name="output_type",
            display_name="Output Type",
            options=["Message", "Data", "DataFrame"],
            info="Select the desired output data type",
            real_time_refresh=True,
            value="Message",
        ),
    ]

    outputs = [
        Output(
            display_name="Message Output",
            name="message_output",
            method="convert_to_message",
        )
    ]

    def update_outputs(self, frontend_node: dict, field_name: str, field_value: Any) -> dict:
        if field_name == "output_type":
            frontend_node["outputs"] = []

            if field_value == "Message":
                frontend_node["outputs"].append(
                    Output(
                        display_name="Message Output",
                        name="message_output",
                        method="convert_to_message",
                    ).to_dict()
                )
            elif field_value == "Data":
                frontend_node["outputs"].append(
                    Output(
                        display_name="Data Output",
                        name="data_output",
                        method="convert_to_data",
                    ).to_dict()
                )
            elif field_value == "DataFrame":
                frontend_node["outputs"].append(
                    Output(
                        display_name="DataFrame Output",
                        name="dataframe_output",
                        method="convert_to_dataframe",
                    ).to_dict()
                )

        return frontend_node

    def convert_to_message(self) -> Message:
        input_value = self.input_data[0] if isinstance(self.input_data, list) else self.input_data
        if isinstance(input_value, str):
            input_value = Message(text=input_value)

        result = convert_to_message(input_value)
        self.status = result
        return result

    def convert_to_data(self) -> Data:
        input_value = self.input_data[0] if isinstance(self.input_data, list) else self.input_data
        if isinstance(input_value, str):
            input_value = Message(text=input_value)

        result = convert_to_data(input_value)
        self.status = result
        return result

    def convert_to_dataframe(self) -> DataFrame:
        input_value = self.input_data[0] if isinstance(self.input_data, list) else self.input_data
        if isinstance(input_value, str):
            input_value = Message(text=input_value)

        result = convert_to_dataframe(input_value)
        self.status = result
        return result

